const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Членове</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Немският член не винаги съвпада с рода на думата в български. Затова съществителните е най-добре да се учат заедно с члена.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примери за членове</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — маса</div>\n      <div class=\"kurss-example\">die Tür — врата</div>\n      <div class=\"kurss-example\">das Messer — нож</div>\n      <div class=\"kurss-example\">das Mädchen — момиче</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Често DER</h4>\n    <p class=\"artikuli-explain\">С DER често са лицата от мъжки пол, дните, месеците, сезоните и някои думи с определени окончания.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → често DER, например: der Computer, der Lehrer <span class=\"artikuli-note\">но не винаги</span></div>\n      <div class=\"kurss-example\">-ling → често DER, например: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → често DER, например: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">лица от мъжки пол → der Mann, der Vater</div>\n      <div class=\"kurss-example\">професии → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">марки автомобили → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">дни → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">месеци → der August, der Dezember</div>\n      <div class=\"kurss-example\">сезони → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примери</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — мъж</div>\n      <div class=\"kurss-example\">der Vater — баща</div>\n      <div class=\"kurss-example\">der Montag — понеделник</div>\n      <div class=\"kurss-example\">der August — август</div>\n      <div class=\"kurss-example\">der Sommer — лято</div>\n      <div class=\"kurss-example\">der Lehrer — учител</div>\n      <div class=\"kurss-example\">der Computer — компютър</div>\n      <div class=\"kurss-example\">der Schmetterling — пеперуда</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Често DIE</h4>\n    <p class=\"artikuli-explain\">С DIE често са лицата от женски пол, множественото число и думите с окончания -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">лица от женски пол → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">марки мотоциклети → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">множествено число → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">множествено число почти винаги → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примери</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — жена</div>\n      <div class=\"kurss-example\">die Mutter — майка</div>\n      <div class=\"kurss-example\">die Wohnung — апартамент</div>\n      <div class=\"kurss-example\">die Rechnung — сметка</div>\n      <div class=\"kurss-example\">die Freiheit — свобода</div>\n      <div class=\"kurss-example\">die Möglichkeit — възможност</div>\n      <div class=\"kurss-example\">die Mannschaft — отбор</div>\n      <div class=\"kurss-example\">die Nation — нация</div>\n      <div class=\"kurss-example\">die Universität — университет</div>\n      <div class=\"kurss-example\">die Polizei — полиция</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Често DAS</h4>\n    <p class=\"artikuli-explain\">С DAS често са умалителните с -chen / -lein, много думи с -ment / -um и глаголите, използвани като съществителни.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">метали → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">химични елементи → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">хотели → das Hotel</div>\n      <div class=\"kurss-example\">цветове като съществителни → das Rot, das Blau</div>\n      <div class=\"kurss-example\">глагол като съществително → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">глаголи като съществителни → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примери</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — дете</div>\n      <div class=\"kurss-example\">das Mädchen — момиче</div>\n      <div class=\"kurss-example\">das Häuschen — къщичка</div>\n      <div class=\"kurss-example\">das Instrument — инструмент</div>\n      <div class=\"kurss-example\">das Zentrum — център</div>\n      <div class=\"kurss-example\">das Museum — музей</div>\n      <div class=\"kurss-example\">das Essen — хранене / храна</div>\n      <div class=\"kurss-example\">das Lernen — учене</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Важни изключения / учи ги с члена</h4>\n    <p class=\"artikuli-explain\">При някои думи членът не може да се определи сигурно по окончанието или по рода на думата в български. Тях е най-добре да ги учиш заедно с члена.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — врата</div>\n      <div class=\"kurss-example\">das Messer — нож</div>\n      <div class=\"kurss-example\">die Sonne — слънце</div>\n      <div class=\"kurss-example\">der Mond — луна</div>\n      <div class=\"kurss-example\">das Mädchen — момиче</div>\n      <div class=\"kurss-example\">das Auto — автомобил</div>\n      <div class=\"kurss-example\">der Käse — сирене</div>\n      <div class=\"kurss-example\">die Gabel — вилица</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Окончанията и групите думи помагат да познаеш члена, но не са 100% сигурно правило. Ако не си сигурен, учи думата заедно с члена.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Местоимения</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ и Dativ — форми на местоименията.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — кой?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — аз</div><div class=\"kurss-example\">du — ти</div><div class=\"kurss-example\">er — той</div><div class=\"kurss-example\">sie — тя</div><div class=\"kurss-example\">es — то</div><div class=\"kurss-example\">wir — ние</div><div class=\"kurss-example\">ihr — вие</div><div class=\"kurss-example\">sie — те</div><div class=\"kurss-example\">Sie — Вие (учтиво)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — кого?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — мен / ме</div><div class=\"kurss-example\">dich — теб / те</div><div class=\"kurss-example\">ihn — него / го (м.р.)</div><div class=\"kurss-example\">sie — нея / я (ж.р.)</div><div class=\"kurss-example\">es — него / го</div><div class=\"kurss-example\">uns — нас / ни</div><div class=\"kurss-example\">euch — вас / ви</div><div class=\"kurss-example\">sie — тях / ги</div><div class=\"kurss-example\">Sie — Вас / Ви (учтиво)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — на кого?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — на мен / ми</div><div class=\"kurss-example\">dir — на теб / ти</div><div class=\"kurss-example\">ihm — на него / му</div><div class=\"kurss-example\">ihr — на нея / ѝ</div><div class=\"kurss-example\">uns — на нас / ни</div><div class=\"kurss-example\">euch — на вас / ви</div><div class=\"kurss-example\">ihnen — на тях / им</div><div class=\"kurss-example\">Ihnen — на Вас / Ви (учтиво)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Как да изберем формата?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — подлог (кой извършва действието?)</li><li><span class=\"case-red\">Akkusativ</span> — пряко допълнение (кого?)</li><li><span class=\"case-green\">Dativ</span> — непряко допълнение (на кого?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примери</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Виждам те.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Виждам го.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Харесваме ви.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Помагам ти.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Давам му книга.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Благодарим ви.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ винаги е подлогът, а Akkusativ и Dativ — допълненията. Погледни глагола и попитай: <span class=\"case-red\">кого?</span> или <span class=\"case-green\">на кого?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Гласни — дълги и кратки</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>В немския език гласните могат да бъдат дълги или кратки. Това влияе на произношението на думата.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Дълга гласна</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (варм) — топъл</div><div class=\"kurss-example\">gut (гӯт) — добър</div><div class=\"kurss-example\">Tat (та̄т) — дело / постъпка</div><div class=\"kurss-example\">Flur (флӯр) — коридор</div><div class=\"kurss-example\">Weg (ве̄к) — път</div><div class=\"kurss-example\">Hut (хӯт) — шапка</div><div class=\"kurss-example\">Hof (хо̄ф) — двор</div><div class=\"kurss-example\">Schlaf (шла̄ф) — сън</div></div>\n              <p class=\"artikuli-explain\">Ако след гласната следва една съгласна, гласната често се произнася дълго.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Кратка гласна</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (пилц) — гъба</div><div class=\"kurss-example\">Wort (ворт) — дума</div><div class=\"kurss-example\">Mund (мунт) — уста</div><div class=\"kurss-example\">bald (балт) — скоро</div><div class=\"kurss-example\">scharf (шарф) — остър</div><div class=\"kurss-example\">Feld (фелт) — поле</div><div class=\"kurss-example\">voll (фол) — пълен</div></div>\n              <p class=\"artikuli-explain\">Ако след гласната следват две или повече съгласни, гласната често се произнася кратко.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Окончания en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (зинген) — пея</div><div class=\"kurss-example\">tragen (тра̄ген) — нося</div><div class=\"kurss-example\">Garten (гартен) — градина</div><div class=\"kurss-example\">Vogel (фо̄гел) — птица</div><div class=\"kurss-example\">Segel (зе̄гел) — платно (на кораб)</div><div class=\"kurss-example\">Braten (бра̄тен) — печено</div><div class=\"kurss-example\">Bogen (бо̄ген) — дъга / лък</div><div class=\"kurss-example\">Spiegel (шпӣгел) — огледало</div><div class=\"kurss-example\">Finger (фингер) — пръст</div><div class=\"kurss-example\">Halter (халтер) — държач</div><div class=\"kurss-example\">Arbeiter (арбайтер) — работник</div><div class=\"kurss-example\">Häuser (хойзер) — къщи</div><div class=\"kurss-example\">wieder (вӣдер) — отново</div><div class=\"kurss-example\">breiter (брайтер) — по-широк</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Буквата h като знак за дължина</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (ра̄мен) — рамка</div><div class=\"kurss-example\">Ohr (о̄р) — ухо</div><div class=\"kurss-example\">Kohle (ко̄ле) — въглища</div><div class=\"kurss-example\">Zahl (ца̄л) — число</div><div class=\"kurss-example\">ihn (ӣн) — него</div><div class=\"kurss-example\">ihm (ӣм) — на него / му</div><div class=\"kurss-example\">Huhn (хӯн) — кокошка</div><div class=\"kurss-example\">nahm (на̄м) — взе</div><div class=\"kurss-example\">nehmen (не̄мен) — вземам</div><div class=\"kurss-example\">Schuh (шӯ) — обувка</div></div>\n              <p class=\"artikuli-explain\">В някои думи h удължава предходната гласна. В тези случаи h обикновено не се произнася.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Окончания с e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (лампе) — лампа</div><div class=\"kurss-example\">Hase (ха̄зе) — заек</div><div class=\"kurss-example\">Knabe (кна̄бе) — момче</div><div class=\"kurss-example\">Rabe (ра̄бе) — гарван</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Дълго i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (дӣ) — определителен член „die“</div><div class=\"kurss-example\">diese (дӣзе) — тази / тези</div><div class=\"kurss-example\">wieder (вӣдер) — отново</div><div class=\"kurss-example\">Fliege (флӣге) — муха</div><div class=\"kurss-example\">Ziege (цӣге) — коза</div><div class=\"kurss-example\">Stiel (штӣл) — дръжка / стъбло</div><div class=\"kurss-example\">Dieb (дӣп) — крадец</div><div class=\"kurss-example\">hier (хӣр) — тук</div></div>\n              <p class=\"artikuli-explain\">В немския език дългото i често се пише като ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двойни гласни</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (за̄л) — зала</div><div class=\"kurss-example\">Saat (за̄т) — сеитба / семена</div><div class=\"kurss-example\">Staat (шта̄т) — държава</div><div class=\"kurss-example\">Beere (бе̄ре) — зрънце / горски плод</div><div class=\"kurss-example\">See (зе̄) — езеро / море</div><div class=\"kurss-example\">Beet (бе̄т) — леха</div><div class=\"kurss-example\">Boot (бо̄т) — лодка</div><div class=\"kurss-example\">Moor (мо̄р) — блато</div><div class=\"kurss-example\">Moos (мо̄с) — мъх</div></div>\n              <p class=\"artikuli-explain\">Двойните гласни обикновено се произнасят дълго.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (вант) — стена</div><div class=\"kurss-example\">Wände (венде) — стени</div><div class=\"kurss-example\">Vater (фа̄тер) — баща</div><div class=\"kurss-example\">Väter (фе̄тер) — бащи</div><div class=\"kurss-example\">Schrank (шранк) — шкаф</div><div class=\"kurss-example\">Schränke (шренке) — шкафове</div><div class=\"kurss-example\">Bank (банк) — пейка / банка</div><div class=\"kurss-example\">Bänke (бенке) — пейки</div><div class=\"kurss-example\">Tal (та̄л) — долина</div><div class=\"kurss-example\">Täler (те̄лер) — долини</div></div>\n              <p class=\"artikuli-explain\">ä е преглас на a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (ро̄зе) — роза</div><div class=\"kurss-example\">Röschen (рьо̄схен) — розичка</div><div class=\"kurss-example\">Ofen (о̄фен) — печка</div><div class=\"kurss-example\">Öfen (ьо̄фен) — печки</div><div class=\"kurss-example\">Rock (рок) — пола</div><div class=\"kurss-example\">Röcke (рьоке) — поли</div></div>\n              <p class=\"artikuli-explain\">ö е преглас на o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (курц) — къс / кратък</div><div class=\"kurss-example\">kürzer (кюрцер) — по-къс / по-кратък</div><div class=\"kurss-example\">Kunst (кунст) — изкуство</div><div class=\"kurss-example\">Künste (кюнсте) — изкуства</div><div class=\"kurss-example\">Mutter (мутер) — майка</div><div class=\"kurss-example\">Mütter (мютер) — майки</div></div>\n              <p class=\"artikuli-explain\">ü е преглас на u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двугласни: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (баум) — дърво</div><div class=\"kurss-example\">Bäume (бойме) — дървета</div><div class=\"kurss-example\">Haus (хаус) — къща</div><div class=\"kurss-example\">Häuser (хойзер) — къщи</div><div class=\"kurss-example\">Strauch (штраух) — храст</div><div class=\"kurss-example\">Sträucher (штройхер) — храсти</div><div class=\"kurss-example\">Maus (маус) — мишка</div><div class=\"kurss-example\">Mäuse (мойзе) — мишки</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двугласни: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (хойте) — днес</div><div class=\"kurss-example\">Leute (лойте) — хора</div><div class=\"kurss-example\">neu (ной) — нов</div><div class=\"kurss-example\">neun (нойн) — девет</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двугласни: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (майн) — мой</div><div class=\"kurss-example\">dein (дайн) — твой</div><div class=\"kurss-example\">sein (зайн) — негов / бъда (съм)</div><div class=\"kurss-example\">frei (фрай) — свободен</div><div class=\"kurss-example\">arbeiten (арбайтен) — работя</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Бележки за произношението към урок 2</h4>\n              <ul class=\"kurss-summary-list\"><li>в думите ich, nicht, rechnen, zeichnen „ch“ се произнася меко (като меко „х“, близко до „хь“)</li><li>в думите arbeiten и zeichnen „ei“ се произнася като „ай“</li><li>„sp“ в началото на думата се произнася като „шп“</li><li>в глагола tun буквата „u“ се произнася дълго</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Обобщение</h4>\n              <ul class=\"kurss-summary-list\"><li>една съгласна след гласната → често дълга гласна</li><li>две или повече съгласни → често кратка гласна</li><li>h може да удължи гласната</li><li>ie често означава дълго i</li><li>двойните гласни обикновено са дълги</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Съгласни и буквосъчетания</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>В немския език някои съгласни и буквосъчетания се произнасят различно от начина, по който се пишат. В този урок са най-важните примери за начинаещи.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Съгласни</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (ра̄т) — колело</div><div class=\"kurss-example\">die Räder (ре̄дер) — колела</div><div class=\"kurss-example\">Bad (ба̄т) — баня</div><div class=\"kurss-example\">Bäder (бе̄дер) — бани</div></div>\n              <p class=\"artikuli-explain\">В края на думата съгласните често не се произнасят така, както се пишат.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">„ch“ може да се произнася меко или твърдо. В някои думи звучи като меко „х“ (близко до „хь“), в други – като твърдо „х“, по-близо до „к“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (рехнен) — смятам</div><div class=\"kurss-example\">zeichnen (цайхнен) — рисувам</div><div class=\"kurss-example\">nicht (нихт) — не</div><div class=\"kurss-example\">schlecht (шлехт) — лош</div><div class=\"kurss-example\">mich (мих) — мен / ме</div><div class=\"kurss-example\">dich (дих) — теб / те</div><div class=\"kurss-example\">Strauch (штраух) — храст</div><div class=\"kurss-example\">noch (нох) — още</div><div class=\"kurss-example\">Nacht (нахт) — нощ</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">„sch“ в немския език се произнася като българското „ш“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (шӯле) — училище</div><div class=\"kurss-example\">Schüler (шю̄лер) — ученик</div><div class=\"kurss-example\">Schiff (шиф) — кораб</div><div class=\"kurss-example\">Schraube (шраубе) — винт</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp и st в началото на думата</h4>\n              <p class=\"artikuli-explain\">В началото на думата или сричката „sp“ често се произнася като „шп“, а „st“ – като „шт“ (т.е. „щ“).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (шпӣлен) — играя</div><div class=\"kurss-example\">Sprung (шпрунг) — скок</div><div class=\"kurss-example\">stehen (ште̄ен) — стоя</div><div class=\"kurss-example\">Stall (штал) — обор</div><div class=\"kurss-example\">Stand (штант) — положение / щанд</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">„qu“ в немския език обикновено се произнася като „кв“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (ква̄л) — мъка / мъчение</div><div class=\"kurss-example\">Quartier (квартӣр) — квартира / квартал</div><div class=\"kurss-example\">quer (кве̄р) — напречно</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s и z</h4>\n              <p class=\"artikuli-explain\">В началото на думата „s“ често звучи като „з“. Буквата „z“ в немския език звучи като българското „ц“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (за̄ген) — казвам</div><div class=\"kurss-example\">singen (зинген) — пея</div><div class=\"kurss-example\">Rose (ро̄зе) — роза</div><div class=\"kurss-example\">Zahl (ца̄л) — число</div><div class=\"kurss-example\">Zeit (цайт) — време</div><div class=\"kurss-example\">Zink (цинк) — цинк</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">В немския език „v“ често се произнася като „ф“. В чуждиците често звучи като българското „в“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (фа̄тер) — баща</div><div class=\"kurss-example\">von (фон) — от</div><div class=\"kurss-example\">viel (фӣл) — много</div><div class=\"kurss-example\">vier (фӣр) — четири</div><div class=\"kurss-example\">Villa (вила) — вила</div><div class=\"kurss-example\">Klavier (клавӣр) — пиано</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x и y</h4>\n              <p class=\"artikuli-explain\">„x“ се произнася като „кс“. „y“ в някои думи се произнася като „ü“ (близко до „ю“).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (фе̄ликс) — Феликс</div><div class=\"kurss-example\">Axt (акст) — брадва</div><div class=\"kurss-example\">Mystik (мюстик) — мистика</div><div class=\"kurss-example\">Mythe (мю̄те) — мит</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">„ß“ в немския език се произнася като „с“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (фӯс) — стъпало (крак)</div><div class=\"kurss-example\">Füße (фю̄се) — стъпала (крака)</div><div class=\"kurss-example\">Grüße (грю̄се) — поздрави</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Обобщение</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ш</li><li>sp / st в началото → шп / шт</li><li>qu → кв</li><li>z → ц</li><li>v често → ф</li><li>x → кс</li><li>ß → с</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Основи на глаголите</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Глаголи от урок 1 и техните форми (спрежение)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Глаголи</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — идвам</div><div class=\"kurss-example\">gehen — отивам</div><div class=\"kurss-example\">stehen — стоя (прав)</div><div class=\"kurss-example\">singen — пея</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — аз идвам</div><div class=\"kurss-example\">du kommst — ти идваш</div><div class=\"kurss-example\">er kommt — той идва</div><div class=\"kurss-example\">sie kommt — тя идва</div><div class=\"kurss-example\">wir kommen — ние идваме</div><div class=\"kurss-example\">ihr kommt — вие идвате</div><div class=\"kurss-example\">sie kommen — те идват</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — аз отивам</div><div class=\"kurss-example\">du gehst — ти отиваш</div><div class=\"kurss-example\">er geht — той отива</div><div class=\"kurss-example\">sie geht — тя отива</div><div class=\"kurss-example\">wir gehen — ние отиваме</div><div class=\"kurss-example\">ihr geht — вие отивате</div><div class=\"kurss-example\">sie gehen — те отиват</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — аз стоя</div><div class=\"kurss-example\">du stehst — ти стоиш</div><div class=\"kurss-example\">er steht — той стои</div><div class=\"kurss-example\">sie steht — тя стои</div><div class=\"kurss-example\">wir stehen — ние стоим</div><div class=\"kurss-example\">ihr steht — вие стоите</div><div class=\"kurss-example\">sie stehen — те стоят</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — аз пея</div><div class=\"kurss-example\">du singst — ти пееш</div><div class=\"kurss-example\">er singt — той пее</div><div class=\"kurss-example\">sie singt — тя пее</div><div class=\"kurss-example\">wir singen — ние пеем</div><div class=\"kurss-example\">ihr singt — вие пеете</div><div class=\"kurss-example\">sie singen — те пеят</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Глаголи от урок 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — играя</div><div class=\"kurss-example\">arbeiten — работя</div><div class=\"kurss-example\">fragen — питам</div><div class=\"kurss-example\">antworten — отговарям</div><div class=\"kurss-example\">rechnen — смятам</div><div class=\"kurss-example\">zeichnen — рисувам</div><div class=\"kurss-example\">tun — правя</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — аз играя</div><div class=\"kurss-example\">du spielst — ти играеш</div><div class=\"kurss-example\">er spielt — той играе</div><div class=\"kurss-example\">sie spielt — тя играе</div><div class=\"kurss-example\">wir spielen — ние играем</div><div class=\"kurss-example\">ihr spielt — вие играете</div><div class=\"kurss-example\">sie spielen — те играят</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — аз работя</div><div class=\"kurss-example\">du arbeitest — ти работиш</div><div class=\"kurss-example\">er arbeitet — той работи</div><div class=\"kurss-example\">sie arbeitet — тя работи</div><div class=\"kurss-example\">wir arbeiten — ние работим</div><div class=\"kurss-example\">ihr arbeitet — вие работите</div><div class=\"kurss-example\">sie arbeiten — те работят</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — аз питам</div><div class=\"kurss-example\">du fragst — ти питаш</div><div class=\"kurss-example\">er fragt — той пита</div><div class=\"kurss-example\">sie fragt — тя пита</div><div class=\"kurss-example\">wir fragen — ние питаме</div><div class=\"kurss-example\">ihr fragt — вие питате</div><div class=\"kurss-example\">sie fragen — те питат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — аз отговарям</div><div class=\"kurss-example\">du antwortest — ти отговаряш</div><div class=\"kurss-example\">er antwortet — той отговаря</div><div class=\"kurss-example\">sie antwortet — тя отговаря</div><div class=\"kurss-example\">wir antworten — ние отговаряме</div><div class=\"kurss-example\">ihr antwortet — вие отговаряте</div><div class=\"kurss-example\">sie antworten — те отговарят</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — аз смятам</div><div class=\"kurss-example\">du rechnest — ти смяташ</div><div class=\"kurss-example\">er rechnet — той смята</div><div class=\"kurss-example\">sie rechnet — тя смята</div><div class=\"kurss-example\">wir rechnen — ние смятаме</div><div class=\"kurss-example\">ihr rechnet — вие смятате</div><div class=\"kurss-example\">sie rechnen — те смятат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — аз рисувам</div><div class=\"kurss-example\">du zeichnest — ти рисуваш</div><div class=\"kurss-example\">er zeichnet — той рисува</div><div class=\"kurss-example\">sie zeichnet — тя рисува</div><div class=\"kurss-example\">wir zeichnen — ние рисуваме</div><div class=\"kurss-example\">ihr zeichnet — вие рисувате</div><div class=\"kurss-example\">sie zeichnen — те рисуват</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — аз правя</div><div class=\"kurss-example\">du tust — ти правиш</div><div class=\"kurss-example\">er tut — той прави</div><div class=\"kurss-example\">sie tut — тя прави</div><div class=\"kurss-example\">wir tun — ние правим</div><div class=\"kurss-example\">ihr tut — вие правите</div><div class=\"kurss-example\">sie tun — те правят</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Строеж на изречението</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Във въпросителното изречение глаголът в немския език обикновено стои на първо място.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Примери</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Ти идваш.</div><div class=\"kurss-example\">Kommst du? — Идваш ли?</div><div class=\"kurss-example\">Er singt. — Той пее.</div><div class=\"kurss-example\">Singt er? — Пее ли той?</div><div class=\"kurss-example\">Stehst du? — Стоиш ли?</div><div class=\"kurss-example\">Ja, ich stehe. — Да, стоя.</div><div class=\"kurss-example\">Geht ihr? — Отивате ли?</div><div class=\"kurss-example\">Ja, wir gehen. — Да, отиваме.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Въпроси с „was“</h4>\n              <p class=\"artikuli-explain\">Ако въпросът започва с въпросителна дума, глаголът в немския език обикновено стои веднага след въпросителната дума.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Какво правиш ти?</div><div class=\"kurss-example\">Was tut er? — Какво прави той?</div><div class=\"kurss-example\">Was tut sie? — Какво прави тя?</div><div class=\"kurss-example\">Was tun sie? — Какво правят те?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Отрицание с „nicht“</h4>\n              <p class=\"artikuli-explain\">Ако отрицанието „nicht“ се отнася до глагола, то в немския език обикновено стои след глагола.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Аз не играя.</div><div class=\"kurss-example\">Paul fragt nicht. — Паул не пита.</div><div class=\"kurss-example\">Er kommt nicht. — Той не идва.</div><div class=\"kurss-example\">Sie singen nicht. — Те не пеят.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Изречения от урок 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Играеш ли?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Не, не играя, работя.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Паул не пита, той работи.</div><div class=\"kurss-example\">Arbeitest du? — Работиш ли?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Не, не работя, пея.</div><div class=\"kurss-example\">Was tut Paul? — Какво прави Паул?</div><div class=\"kurss-example\">Er spielt. — Той играе.</div><div class=\"kurss-example\">Was tut Marie? — Какво прави Мари?</div><div class=\"kurss-example\">Sie singt. — Тя пее.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Паул играе, а Мари пее.</div><div class=\"kurss-example\">Singt ihr? — Пеете ли?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Не, не пеем, работим.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Какво правят Паул и Мари?</div><div class=\"kurss-example\">Sie fragen. — Те питат.</div><div class=\"kurss-example\">Sie antworten nicht. — Те не отговарят.</div><div class=\"kurss-example\">Wer arbeitet? — Кой работи?</div><div class=\"kurss-example\">Wir arbeiten. — Ние работим.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Ние смятаме и рисуваме.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Те идват, питат, отговарят, работят, играят, пеят и отиват.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Урок 2</h3>\n            <p class=\"kurss-lesson-intro\">Втори урок: диалози, думи, произношение, граматика и превод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалози / изречения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — играя; свиря</div>\n                  <div class=\"kurss-example\">nein — не</div>\n                  <div class=\"kurss-example\">nicht — не</div>\n                  <div class=\"kurss-example\">arbeiten — работя</div>\n                  <div class=\"kurss-example\">fragen — питам</div>\n                  <div class=\"kurss-example\">was tut er? — какво прави той?</div>\n                  <div class=\"kurss-example\">was tun sie? — какво правят те?</div>\n                  <div class=\"kurss-example\">aber — но</div>\n                  <div class=\"kurss-example\">antworten — отговарям</div>\n                  <div class=\"kurss-example\">rechnen — смятам</div>\n                  <div class=\"kurss-example\">zeichnen — рисувам</div>\n                  <div class=\"kurss-example\">Marie — Мария</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В думите ich, nicht, rechnen, zeichnen звукът ch се произнася меко, приблизително като мекото българско х в думи като химия, хирург.</div><div class=\"kurss-example\">В думите arbeiten, zeichnen дифтонгът ei се произнася приблизително като българското „ай“.</div><div class=\"kurss-example\">Съчетанието от съгласни sp се произнася като шп: spielen (шпилен).</div><div class=\"kurss-example\">В глагола tun u се произнася дълго във всички лица.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Окончания с e</h4>\n                  <div class=\"lesson1-grammar-note\">Ако основата на глагола завършва на t, d, chn, при спрежението пред окончанията -st и -t стои e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Въпросителна дума</h4>\n                  <div class=\"lesson1-grammar-note\">Във въпросителните изречения, които започват с въпросителна дума, например: какво? кой? кой от тях? защо? по каква причина? и т.н., глаголът стои веднага след въпросителната дума.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Какво правиш?</div><div class=\"kurss-example\">Was tut er? — Какво прави той?</div><div class=\"kurss-example\">Was tut sie? — Какво прави тя?</div><div class=\"kurss-example\">Was tun sie? — Какво правят те?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Отрицание с nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Когато отрицанието nicht се отнася до глагола, отрицателната дума стои след глагола.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Той не идва.</div><div class=\"kurss-example\">Sie singen nicht. — Те не пеят.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 2: карта за превод\">\n                    <span class=\"lesson1-training-progress\">Урок 2 · Преведи: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Кой пита?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Кликни върху картата, за да видиш немския превод. След отговора следващото кликване показва следващата карта.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Урок 6</h3>\n    <p class=\"kurss-lesson-intro\">Числа, множествено число, умлаути и форми за множествено число на съществителните.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалози / изречения</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — намира се, има, лежи</div><div class=\"kurss-example\">der Bleistift (блайщифт) — молив</div><div class=\"kurss-example\">einige (айниге) — няколко</div><div class=\"kurss-example\">hinlegen — оставям</div><div class=\"kurss-example\">legt hin — оставя</div><div class=\"kurss-example\">wieder (видер) — отново</div><div class=\"kurss-example\">aufmachen — отварям</div><div class=\"kurss-example\">er macht auf — той отваря</div><div class=\"kurss-example\">anspitzen (аншпицен) — подострям</div><div class=\"kurss-example\">er spitzt an — той подостря</div><div class=\"kurss-example\">sich setzen — сядам</div><div class=\"kurss-example\">setzt sich — сяда</div><div class=\"kurss-example\">der Schlüssel (шлюсел) — ключ</div><div class=\"kurss-example\">das Fenster (фенстер) — прозорец</div><div class=\"kurss-example\">die Tafel (ди тафел) — дъска</div><div class=\"kurss-example\">der Garten — градина</div><div class=\"kurss-example\">der Löffel — лъжица</div><div class=\"kurss-example\">zählen (целен) — броя</div><div class=\"kurss-example\">die Nadel — игла</div><div class=\"kurss-example\">was ist das — какво е това?</div><div class=\"kurss-example\">der Hammer — чук</div><div class=\"kurss-example\">die Hämmer — чукове</div><div class=\"kurss-example\">der Deckel (дер декел) — капак</div><div class=\"kurss-example\">der Teller — чиния</div><div class=\"kurss-example\">der Wagen — каруца</div><div class=\"kurss-example\">der Schlitten — шейна</div><div class=\"kurss-example\">das Ding — нещо, вещ</div><div class=\"kurss-example\">die Dinge — неща, вещи</div><div class=\"kurss-example\">wie sind die Dinge? — какви са нещата?</div><div class=\"kurss-example\">voll (фол) — пълен</div><div class=\"kurss-example\">leer (лер) — празен</div><div class=\"kurss-example\">schwer (швер) — тежък, труден</div><div class=\"kurss-example\">leicht — лек</div><div class=\"kurss-example\">der Eimer — кофа</div><div class=\"kurss-example\">wieviel (вифил) — колко</div><div class=\"kurss-example\">wieviel Nadeln — колко игли</div><div class=\"kurss-example\">hier (хир) — тук</div><div class=\"kurss-example\">dort — там</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä е умлаут на гласната a и се произнася като кратко или дълго затворено е.</div><div class=\"kurss-example\">Примери: das Mädchen (метхен), die Bänke (ди бенке), der Vater (дер фатер), die Väter (ди фетер).</div><div class=\"kurss-example\">ü е умлаут на гласната u. При произнасянето му устните трябва силно да се закръглят и със закръглени устни да се опитате да произнесете и.</div><div class=\"kurss-example\">Примери: fünf, der Schlüssel (шлюсел).</div><div class=\"kurss-example\">ö се произнася със закръглени устни, като се опитвате да произнесете е: der Löffel.</div><div class=\"kurss-example\">Удвоената гласна означава дълга гласна: leer (лер).</div><div class=\"kurss-example\">Дифтонгът eu се произнася като ой: neun (нойн).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Граматика и обяснения</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ударената представка на сложния глагол в сегашно време се отделя от глагола и стои в края на изречението.</div><div class=\"kurss-example\">Примери: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Числителното „един“ има форма и в трите рода, когато се използва със съществително: в мъжки род ein, в женски род eine, в среден род ein.</div><div class=\"kurss-example\">Примери: ein Schüler — един ученик; eine Schülerin — една ученичка; ein Kind — едно дете.</div><div class=\"kurss-example\">Числа: eins, zwei, drei, vier (фир), fünf, sechs (зекс), sieben (зибен), acht, neun (нойн), zehn (цен).</div><div class=\"kurss-example\">Глаголът-връзка в немския има форма за единствено и за множествено число: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Показателните местоимения в българския се променят по род и число, но в немския в такива изречения се използва една форма, както българското „това“ в „това е…“, „това са…“: das.</div><div class=\"kurss-example\">Примери: това е чук — das ist ein Hammer; това е игла — das ist eine Nadel; това са чукове — das sind Hämmer; това са игли — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — каруца и der Schlitten — шейна в немския се използват както в единствено, така и в множествено число.</div><div class=\"kurss-example\">Съществителните от мъжки и среден род с окончание -er, -el, -en често не получават окончание в множествено число.</div><div class=\"kurss-example\">Примери: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Съществителните от женски род с окончание -el, -er получават -n в множествено число.</div><div class=\"kurss-example\">Примери: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Изключения: die Mutter (майка) — die Mütter (майки); die Tochter (дъщеря) — die Töchter (дъщери).</div><div class=\"kurss-example\">Неопределителният член няма множествено число: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">В съобщителното изречение глаголът, който е сказуемо, стои на второ място: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 6: карта за превод\"><span class=\"lesson1-training-progress\">Урок 6 · Преведи: 1 / 21</span><span class=\"lesson1-training-text\">Паул взема молив и рисува.</span></button><p class=\"lesson1-training-hint\">Кликни върху картата, за да видиш немския превод. След отговора следващото кликване показва следващата карта.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Урок 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, акузатив, sitzen, fragen и наставката -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалози / изречения</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (зицен) — седя</div>\n        <div class=\"kurss-example\">fragen (фраген) — питам</div>\n        <div class=\"kurss-example\">der Lehrer (дер лерер) — учител</div>\n        <div class=\"kurss-example\">gut (гут) — добре</div>\n        <div class=\"kurss-example\">wen (вен) — кого</div>\n        <div class=\"kurss-example\">loben — хваля</div>\n        <div class=\"kurss-example\">der Schüler (шюлер) — ученик</div>\n        <div class=\"kurss-example\">klein — малък</div>\n        <div class=\"kurss-example\">groß (грос) — голям</div>\n        <div class=\"kurss-example\">die Lehrerin — учителка</div>\n        <div class=\"kurss-example\">die Schülerin — ученичка</div>\n        <div class=\"kurss-example\">schlecht (шлехт) — зле</div>\n        <div class=\"kurss-example\">tadeln — порицавам, укорявам</div>\n        <div class=\"kurss-example\">oder (одер) — или</div>\n        <div class=\"kurss-example\">das Kind (кинт) — дете</div>\n        <div class=\"kurss-example\">artig (артих) — послушен</div>\n        <div class=\"kurss-example\">die Mutter — майка</div>\n        <div class=\"kurss-example\">lieben (либен) — обичам</div>\n        <div class=\"kurss-example\">der Vater (фатер) — баща</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz е удвоен звук z и се произнася като ц: sitzen (зицен).</div>\n        <div class=\"kurss-example\">В немските думи v се произнася като ф: der Vater (фатер).</div>\n        <div class=\"kurss-example\">ß се нарича есцет и се произнася като българското с: groß (грос), weiß (вайс).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Номинатив и акузатив</h4><div class=\"lesson1-grammar-note\">В българския език подлогът отговаря на въпроса кой? / какво?, а прякото допълнение отговаря на въпроса кого? / какво?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В немския въпросът в номинатив е wer? за лица и was? за предмети.</div><div class=\"kurss-example\">В акузатив въпросът е wen? за лица и was? за предмети.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Промяна на члена в акузатив</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + акузатив</h4><div class=\"lesson1-grammar-note\">В немския глаголът fragen изисква акузатив.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Наставка -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Много съществителни от женски род се образуват с наставката -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Място на глагола</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В съобщителното изречение глаголът стои на второ място.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 5: карта за превод\"><span class=\"lesson1-training-progress\">Урок 5 · Преведи: 1 / 16</span><span class=\"lesson1-training-text\">Кого обича бащата?</span></button><p class=\"lesson1-training-hint\">Кликни върху картата, за да видиш немския превод. След отговора следващото кликване показва следващата карта.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Урок 4</h3>\n            <p class=\"kurss-lesson-intro\">Акузатив, nehmen, hinlegen, hinausgehen и прилагателни.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалози / изречения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (немен) — вземам</div><div class=\"kurss-example\">er nimmt (нимт) — той взема</div><div class=\"kurss-example\">der Federhalter (дер федерхалтер) — писалката</div><div class=\"kurss-example\">einen Federhalter — писалка</div><div class=\"kurss-example\">zeigen — показвам</div><div class=\"kurss-example\">schwarz (шварц) — черен</div><div class=\"kurss-example\">weiß (вайс) — бял</div><div class=\"kurss-example\">die Feder (ди федер) — перото</div><div class=\"kurss-example\">eine Feder — перо</div><div class=\"kurss-example\">spitz (шпиц) — заострен</div><div class=\"kurss-example\">hinlegen — оставям</div><div class=\"kurss-example\">legt hin — оставя</div><div class=\"kurss-example\">das Mädchen (метхен) — момиче</div><div class=\"kurss-example\">das Messer — ножът</div><div class=\"kurss-example\">ein Messer — нож</div><div class=\"kurss-example\">scharf — остър</div><div class=\"kurss-example\">stumpf (щумпф) — тъп</div><div class=\"kurss-example\">dann — тогава, след това</div><div class=\"kurss-example\">hinaus — навън</div><div class=\"kurss-example\">hinausgehen — излизам, отивам навън</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Окончанията -en, -er, -el са неударени, затова e в тях се чува слабо: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">В немския h може да бъде както звук, така и знак за дължина на предходната гласна.</div><div class=\"kurss-example\">Когато h е знак за дължина, то не се произнася като звук: nehmen (немен).</div><div class=\"kurss-example\">Когато след гласната следва само една съгласна, гласната се произнася дълго: die (ди) Feder (федер), den (ден).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Акузатив</h4><div class=\"lesson1-grammar-note\">В женски и среден род акузативът съвпада с номинатива. Променя се само мъжкият род.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Местоимения</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — мъжки род</div><div class=\"kurss-example\">sie — женски род</div><div class=\"kurss-example\">es — среден род</div><div class=\"kurss-example\">в множествено число — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Отделяеми глаголи</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Прилагателни</h4><div class=\"lesson1-grammar-note\">Когато прилагателното е част от сказуемото, то не се променя нито по род, нито по число.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Отрицание с nicht</h4><div class=\"lesson1-grammar-note\">Когато nicht отрича прилагателно, то стои пред отричаната дума.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Съществителните с наставка -chen и -lein са от среден род: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 4: карта за превод\"><span class=\"lesson1-training-progress\">Урок 4 · Преведи: 1 / 16</span><span class=\"lesson1-training-text\">Момичето взема писалка.</span></button><p class=\"lesson1-training-hint\">Кликни върху картата, за да видиш немския превод. След отговора следващото кликване показва следващата карта.</p></div></div></details>",
  "kurssLesson3": "            <h3>Урок 3</h3>\n            <p class=\"kurss-lesson-intro\">Трети урок: диалози, думи, произношение, граматика и превод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалози / изречения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — кой</div><div class=\"kurss-example\">was — какво</div><div class=\"kurss-example\">hier — тук</div><div class=\"kurss-example\">dort — там</div><div class=\"kurss-example\">der Tisch — масата</div><div class=\"kurss-example\">ein Tisch — маса</div><div class=\"kurss-example\">die Bank — пейката</div><div class=\"kurss-example\">eine Bank — пейка</div><div class=\"kurss-example\">liegen — лежа</div><div class=\"kurss-example\">liegt hier ein Buch? — лежи ли тук книга?</div><div class=\"kurss-example\">das Buch — книгата</div><div class=\"kurss-example\">ein Buch — книга</div><div class=\"kurss-example\">hängen — вися</div><div class=\"kurss-example\">das Bild — картината</div><div class=\"kurss-example\">ein Bild — картина</div><div class=\"kurss-example\">die Tafel — дъската</div><div class=\"kurss-example\">eine Tafel — дъска</div><div class=\"kurss-example\">wie — какъв, каква</div><div class=\"kurss-example\">ist — е</div><div class=\"kurss-example\">dick — дебел</div><div class=\"kurss-example\">das Heft — тетрадката</div><div class=\"kurss-example\">ein Heft — тетрадка</div><div class=\"kurss-example\">dünn — тънък</div><div class=\"kurss-example\">niedrig — нисък</div><div class=\"kurss-example\">hoch — висок</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Дългият звук и в немския се означава с ie: liegen (лиген), hier (хир), wie (ви).</div><div class=\"kurss-example\">ck е удвоено k: dick (дикк).</div><div class=\"kurss-example\">В прилагателните и наречията окончанието -ig звучи като леко -ich: niedrig (нидрих).</div><div class=\"kurss-example\">Ако след -ig следва e: -ige, g се произнася като ясно г: niedrige (нидриге) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Подлог</h4><div class=\"lesson1-grammar-note\">Подлогът в немския отговаря на въпроса wer? / was? и стои в номинатив.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">С wer? се пита за лица.</div><div class=\"kurss-example\">С was? се пита за предмети.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Членове</h4><div class=\"lesson1-grammar-note\">В немския съществителните имат 3 рода: мъжки, женски и среден. Пред съществителните обикновено стои малка дума, наречена член. Тази дума не се превежда.</div><h5 class=\"lesson2-subtitle\">Определителен член</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">мъжки род — der</div><div class=\"kurss-example\">женски род — die</div><div class=\"kurss-example\">среден род — das</div><div class=\"kurss-example\">В множествено число определителният член и за трите рода е die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Неопределителен член</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">мъжки род — ein</div><div class=\"kurss-example\">женски род — eine</div><div class=\"kurss-example\">среден род — ein</div><div class=\"kurss-example\">Неопределителният член няма множествено число.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Собствени имена</h4><div class=\"lesson1-grammar-note\">Пред собствените имена не се използва член.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Място на глагола</h4><div class=\"lesson1-grammar-note\">В съобщителното изречение глаголът стои на второ място.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">На немски за предмети, които са във вертикално положение, се казва, че стоят:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">За предмети, които са в хоризонтално положение, се казва, че лежат:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Предметите могат и да висят:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 3: карта за превод\"><span class=\"lesson1-training-progress\">Урок 3 · Преведи: 1 / 22</span><span class=\"lesson1-training-text\">Смяташ ли?</span></button><p class=\"lesson1-training-hint\">Кликни върху картата, за да видиш немския превод. След отговора следващото кликване показва следващата карта.</p></div></div></details>",
  "kurssLesson7": "            <h3>Урок 7</h3>\n            <p class=\"kurss-lesson-intro\">Седми урок: повелително наклонение, учтива форма на обръщение и множествено число.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Диалози / изречения</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — пея</div><div class=\"kurss-example\">singe — пей</div><div class=\"kurss-example\">singt — пейте</div><div class=\"kurss-example\">singen Sie — пейте</div><div class=\"kurss-example\">das Lied (дас лит) — песен</div><div class=\"kurss-example\">Sie — Вие</div><div class=\"kurss-example\">zählen — броя</div><div class=\"kurss-example\">das Fräulein (фройлайн) — госпожица</div><div class=\"kurss-example\">der Müller — мелничар</div><div class=\"kurss-example\">öffnen — отварям</div><div class=\"kurss-example\">das Fenster (фенстер) — прозорец</div><div class=\"kurss-example\">alle — всички</div><div class=\"kurss-example\">der Spiegel (шпигел) — огледало</div><div class=\"kurss-example\">der Lappen — парцал</div><div class=\"kurss-example\">der Spaten — лопата</div><div class=\"kurss-example\">der Besen — метла</div><div class=\"kurss-example\">die Schaufel — лопатка</div><div class=\"kurss-example\">die Schüssel — купа</div><div class=\"kurss-example\">das Zimmer — стая</div><div class=\"kurss-example\">das Ufer (уфер) — бряг</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В началото на думата или сричката sp се произнася като шп: der Spiegel (дер шпигел).</div><div class=\"kurss-example\">sch се произнася като българското ш: die Schaufel (ди шауфел), die Schüssel (ди шюсел).</div><div class=\"kurss-example\">Дифтонгът äu се произнася като българското „ой“: das Fräulein (дас фройлайн).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Повелително наклонение</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Повелителното наклонение във 2. лице единствено число съответства на формата на глагола за 2. лице единствено число без личното окончание -st, като се добавя окончанието -e.</div><div class=\"kurss-example\">Примери: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Много често окончанието -e не се използва, ако повелителната форма без него е едносрична: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Повелително наклонение в множествено число</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Повелителната форма във 2. лице множествено число съвпада с 2. лице множествено число в сегашно време, но се използва без местоимение.</div><div class=\"kurss-example\">Примери: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Учтива форма на обръщение със Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Учтивата форма на обръщение с „Вие“ съвпада с 3. лице множествено число. Местоимението Sie се пише с главна буква и стои след глагола.</div><div class=\"kurss-example\">Примери: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">При глагола öffnen за по-лесно произнасяне във 2. и 3. лице единствено число и във 2. лице множествено число между основата и окончанието се вмъква e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Упражнение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 7: карта за упражнение\"><span class=\"lesson1-training-progress\">Урок 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — питам</span></button><p class=\"lesson1-training-hint\">Докосни картата, за да видиш повелителните форми.</p></div></div></details>",
  "kurssLesson1": "            <h3>Урок 1</h3>\n            <p class=\"kurss-lesson-intro\">Първи урок: глаголи в сегашно време, думи, произношение, граматика и превод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Глаголи в сегашно време</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Глаголи и тяхното спрежение в сегашно време.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — идвам</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>аз идвам</span><span>du</span><strong>kommst</strong><span>ти идваш</span><span>er / sie</span><strong>kommt</strong><span>той / тя идва</span><span>wir</span><strong>kommen</strong><span>ние идваме</span><span>ihr</span><strong>kommt</strong><span>вие идвате</span><span>sie / Sie</span><strong>kommen</strong><span>те / Вие идват</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — отивам</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>аз отивам</span><span>du</span><strong>gehst</strong><span>ти отиваш</span><span>er / sie</span><strong>geht</strong><span>той / тя отива</span><span>wir</span><strong>gehen</strong><span>ние отиваме</span><span>ihr</span><strong>geht</strong><span>вие отивате</span><span>sie / Sie</span><strong>gehen</strong><span>те / Вие отиват</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — стоя</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>аз стоя</span><span>du</span><strong>stehst</strong><span>ти стоиш</span><span>er / sie</span><strong>steht</strong><span>той / тя стои</span><span>wir</span><strong>stehen</strong><span>ние стоим</span><span>ihr</span><strong>steht</strong><span>вие стоите</span><span>sie / Sie</span><strong>stehen</strong><span>те / Вие стоят</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — пея</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>аз пея</span><span>du</span><strong>singst</strong><span>ти пееш</span><span>er / sie</span><strong>singt</strong><span>той / тя пее</span><span>wir</span><strong>singen</strong><span>ние пеем</span><span>ihr</span><strong>singt</strong><span>вие пеете</span><span>sie / Sie</span><strong>singen</strong><span>те / Вие пеят</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Примери</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Думи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Приблизителното произношение на думите е дадено в скоби с български букви.<br>Това важи и за следващите уроци.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (вир) — ние</div><div class=\"kurss-example\">В думата „wir“ буквата i се произнася дълго.</div><div class=\"kurss-example\">kommen (комен) — идвам</div><div class=\"kurss-example\">gehen (ге-ен) — отивам</div><div class=\"kurss-example\">stehen (ще-ен) — стоя</div><div class=\"kurss-example\">singen (зинген) — пея</div><div class=\"kurss-example\">du (ду) kommst — ти идваш</div><div class=\"kurss-example\">er (ер) kommt — той идва</div><div class=\"kurss-example\">sie (зи) kommt — тя идва</div><div class=\"kurss-example\">wer (вер) — кой?</div><div class=\"kurss-example\">ja (я) — да</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Произношение</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Правилното произношение на думите, записано с български букви, е дадено в уроците.</div><div class=\"kurss-example\">Wir (вир) — ние. В думата wir „и“ винаги се произнася дълго.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Инфинитив</h4><div class=\"lesson1-grammar-note\">Основна форма на глагола. Обикновено инфинитивът завършва на -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Окончания в сегашно време</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Махни <span class=\"lesson1-ending-accent\">-en</span> от основната форма на глагола и добави окончанието.</strong></p><p>Пример: kommen → komm + окончание</p><div class=\"lesson1-ending-process\" aria-label=\"Как се образуват окончанията в сегашно време\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>основна форма</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>махни <span class=\"lesson1-ending-accent\">-en</span></strong><span>остава коренът</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>корен</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>добави окончание</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Примери</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Въпросителни изречения</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>В немското въпросително изречение глаголът обикновено отива на първо място.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">На български:<br>Ти идваш.<br>Идваш ли ти?</div><div class=\"kurss-example\">На немски:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ти идваш<br>kommst du? — идваш ли?</div><div class=\"kurss-example\">er singt — той пее<br>singt er? — пее ли той?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Разлика в лицето</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — той идва</div><div class=\"kurss-example\">sie kommt — тя идва</div><div class=\"kurss-example\">sie kommen — те идват</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 1: карта за упражнение\">\n                    <span class=\"lesson1-training-progress\">Урок 1 · Преведи: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Идваш ли?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Кликни върху картата, за да видиш немския превод. След отговора следващото кликване показва следващата карта.</p>\n                </div>\n              </div>\n            </details>"
};

